function [G,R]=summarize_q7_dom_group_roi()
repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));root=fullfile(repo,'results','q7_interaction_dom','cohort_specification');G=table();I=table();
for hb=["HbO","HbR"]
 B=[];info=table();for s=1:30,sid=sprintf('subject%03d',s);T=readtable(fullfile(root,sid,sprintf('%s_%s_q7_interaction_dom_channel_contrasts.csv',sid,hb)),'TextType','string');B(s,:)=T.contrast_beta(:)';if isempty(info),info=T(:,{'channel_index','channel_id','channel_type','roi','laterality'});end;end;n=sum(isfinite(B));mu=mean(B,1,'omitnan');sd=std(B,0,1,'omitnan');se=sd./sqrt(n);t=mu./se;p=betainc((n-1)./((n-1)+t.^2),(n-1)/2,.5);q=bh(p);G=[G;table(repmat(hb,61,1),n(:),mu(:),sd(:),se(:),t(:),p(:),q(:),'VariableNames',{'hemoglobin','n_subjects','mean_contrast_beta','sd_contrast_beta','group_se','group_t','group_p_two_sided','group_q_bh61'}),info];for s=1:30,sid=sprintf('subject%03d',s);T=readtable(fullfile(root,sid,sprintf('%s_%s_q7_interaction_dom_channel_contrasts.csv',sid,hb)),'TextType','string');T=T(T.channel_type=="Long",:);K=unique(T(:,{'roi','laterality'}),'rows','stable');for k=1:height(K),x=T(T.roi==K.roi(k)&T.laterality==K.laterality(k),:);I=[I;table(s,hb,K.roi(k),K.laterality(k),height(x),mean(x.contrast_beta),'VariableNames',{'subject_id','hemoglobin','roi','laterality','n_long_channels','mean_contrast_beta'})];end;end
end
writetable(G,fullfile(root,'q7_interaction_dom_group_channel_summary_n30.csv'));R=table();for hb=["HbO","HbR"],H=I(I.hemoglobin==hb,:);K=unique(H(:,{'roi','laterality'}),'rows','stable');p=zeros(height(K),1);for k=1:height(K),x=H.mean_contrast_beta(H.roi==K.roi(k)&H.laterality==K.laterality(k));n=numel(x);se=std(x)/sqrt(n);tt=mean(x)/se;p(k)=betainc(n/(n+tt^2),n/2,.5);R=[R;table(hb,K.roi(k),K.laterality(k),n,mean(x),std(x),se,tt,p(k),'VariableNames',{'hemoglobin','roi','laterality','n_subjects','mean_contrast_beta','sd_contrast_beta','se_contrast_beta','t_statistic','p_value'})];end;end;R.q_value_bh_fdr=bh(R.p_value);writetable(I,fullfile(root,'q7_interaction_dom_individual_ROI_long45_allQC_n30.csv'));writetable(R,fullfile(root,'q7_interaction_dom_group_ROI_long45_allQC_n30.csv'));disp(R);
end
function q=bh(p),[s,o]=sort(p(:));m=numel(s);z=min(1,flipud(cummin(flipud(s*m./(1:m)'))));q=zeros(size(p));q(o)=z;end
